import React, { useEffect, useRef, useState } from 'react';
import './Home.css';

const PANELS = [
  { id: 'banner', title: 'Banner' },
  { id: 'concept', title: 'Concept' },
  { id: 'hands-on', title: 'Hands-on' },
  { id: 'patient-selection', title: 'Patient selection' },
  { id: 'multidisciplinary', title: 'Multidisciplinary' },
  { id: 'international-faculty', title: 'International faculty' },
  { id: 'evidence', title: 'Evidence' },
  { id: 'cme', title: 'CME accredited' },
  { id: 'schedule', title: 'At a glance' },
  { id: 'faculty', title: 'Faculty' },
  { id: 'registration', title: 'Registration' }
];

const Home = () => {
  const deckRef = useRef(null);
  const [activeIndex, setActiveIndex] = useState(0);

  useEffect(() => {
    const deck = deckRef.current;
    if (!deck) return;

    // Handle intersection observer to update dots and hash
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting && entry.intersectionRatio >= 0.5) {
          const index = parseInt(entry.target.dataset.index, 10);
          setActiveIndex(index);
          const panelId = PANELS[index].id;
          if (window.location.hash !== `#${panelId}`) {
            window.history.replaceState(null, null, `#${panelId}`);
          }
        }
      });
    }, {
      root: deck,
      threshold: 0.5
    });

    const panelElements = deck.querySelectorAll('.panel');
    panelElements.forEach(el => observer.observe(el));

    // Wheel event for horizontal scrolling
    const handleWheel = (e) => {
      if (Math.abs(e.deltaY) > Math.abs(e.deltaX)) {
        // Only scroll if we aren't at the very edges fighting scroll back
        const atStart = deck.scrollLeft === 0 && e.deltaY < 0;
        const atEnd = deck.scrollLeft + deck.clientWidth >= deck.scrollWidth && e.deltaY > 0;
        
        if (!atStart && !atEnd) {
          e.preventDefault();
          deck.scrollLeft += e.deltaY;
        }
      }
    };
    
    // Check prefers-reduced-motion
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    
    const handleKeyDown = (e) => {
      let newIndex = activeIndex;
      if (e.key === 'ArrowRight' || e.key === 'PageDown') {
        e.preventDefault();
        newIndex = Math.min(PANELS.length - 1, activeIndex + 1);
      } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
        e.preventDefault();
        newIndex = Math.max(0, activeIndex - 1);
      } else if (e.key === 'Home') {
        e.preventDefault();
        newIndex = 0;
      } else if (e.key === 'End') {
        e.preventDefault();
        newIndex = PANELS.length - 1;
      }

      if (newIndex !== activeIndex) {
        scrollToIndex(newIndex, mediaQuery.matches);
      }
    };

    deck.addEventListener('wheel', handleWheel, { passive: false });
    document.addEventListener('keydown', handleKeyDown);

    // Initial hash sync
    const hash = window.location.hash.slice(1);
    const initialIndex = PANELS.findIndex(p => p.id === hash);
    if (initialIndex > 0) {
      setTimeout(() => {
        scrollToIndex(initialIndex, true);
      }, 100);
    }

    return () => {
      observer.disconnect();
      deck.removeEventListener('wheel', handleWheel);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [activeIndex]);

  const scrollToIndex = (index, immediate = false) => {
    const deck = deckRef.current;
    if (!deck) return;
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    deck.scrollTo({
      left: index * deck.clientWidth,
      behavior: immediate || mediaQuery.matches ? 'auto' : 'smooth'
    });
  };

  const handleRegisterClick = (e) => {
    e.preventDefault();
    alert('Registration opens soon');
  };

  return (
    <>
      <a href="#" onClick={handleRegisterClick} className="reg-pill">Register now</a>

      <button 
        className="nav prev" 
        onClick={() => scrollToIndex(activeIndex - 1)}
        disabled={activeIndex <= 0}
        aria-label="Previous"
      >
        &#8249;
      </button>
      <button 
        className="nav next" 
        onClick={() => scrollToIndex(activeIndex + 1)}
        disabled={activeIndex >= PANELS.length - 1}
        aria-label="Next"
      >
        &#8250;
      </button>

      <div className="dots" role="tablist" aria-label="Sections">
        {PANELS.map((panel, idx) => (
          <button
            key={panel.id}
            className={`dot ${idx === activeIndex ? 'active' : ''}`}
            onClick={() => scrollToIndex(idx)}
            aria-label={`Go to section ${idx + 1}`}
          />
        ))}
      </div>

      <main className="deck" ref={deckRef} id="deck">
        
        {/* Panel 1: Banner / hero */}
        <section className="panel p-banner" id="banner" data-index="0" tabIndex="0" aria-label="Banner">
          <div className="pinner" style={{ textAlign: 'center', maxWidth: '900px' }}>
  <img className="banner-img" src="data:image/png;base64," alt="Thyroid Intervention Summit 2026 · IR CME · 27–28 Nov 2026 · Delhi-NCR · Medanta – The Medicity, Gurgaon and Holiday Inn Aerocity, New Delhi · ISTS 2026 Pre-Conference · IR-Tutorials"/>
            <div className="hint">Swipe to explore <span className="arw">→</span></div>
          </div>
        </section>

        {/* Panel 2: Concept */}
        <section className="panel" id="concept" data-index="1" tabIndex="0" aria-label="About the summit">
          <div className="pinner">
            <p className="eyebrow">About the summit</p>
            <h2 className="ptitle">Thyroid intervention, <em>from every angle</em></h2>
            <p className="ptext">The Thyroid Intervention Summit 2026 brings the full thyroid-nodule pathway into one room — imaging and cytology, patient selection, ablation technique and energy, and the surgical and endocrine perspectives that decide who should be treated and how.</p>
            <div className="who">
              <b>Who it's for</b>
              Organised by Dr. Anubhav Khandelwal — Organising Secretary and Director of Interventional Radiology at Medanta – The Medicity — under Course Director Dr. S. S. Baijal. Around 100 delegates — practising IR, endocrine surgery, nuclear medicine, endocrinology and cytopathology specialists, and DrNB-level trainees — are expected.
            </div>
          </div>
        </section>

        {/* Panel 3: Hands-on RFA & MWA */}
        <section className="panel" id="hands-on" data-index="2" tabIndex="0" aria-label="Hands-on RFA & MWA">
          <div className="pinner">
            <p className="eyebrow">Why attend</p>
            <h2 className="ptitle">Hands-on <em>RFA &amp; MWA</em></h2>
            <p className="ptext">Parallel-rotation stations on Day 1 for radiofrequency and microwave ablation — open to Interventional Radiology / Radiology delegates, limited to 50 seats.</p>
          </div>
        </section>

        {/* Panel 4: Patient selection as the throughline */}
        <section className="panel" id="patient-selection" data-index="3" tabIndex="0" aria-label="Patient selection">
          <div className="pinner">
            <p className="eyebrow">Why attend</p>
            <h2 className="ptitle">Patient selection <em>as the throughline</em></h2>
            <p className="ptext">A dedicated focus on who to treat and when — decision-making surfaced across both days, not buried in a single talk.</p>
          </div>
        </section>

        {/* Panel 5: Truly multidisciplinary */}
        <section className="panel" id="multidisciplinary" data-index="4" tabIndex="0" aria-label="Multidisciplinary">
          <div className="pinner">
            <p className="eyebrow">Why attend</p>
            <h2 className="ptitle">Truly <em>multidisciplinary</em></h2>
            <p className="ptext">IR, endocrine surgery, nuclear medicine, endocrinology and cytopathology on the same faculty and the same panel.</p>
          </div>
        </section>

        {/* Panel 6: International faculty */}
        <section className="panel" id="international-faculty" data-index="5" tabIndex="0" aria-label="International faculty">
          <div className="pinner">
            <p className="eyebrow">Why attend</p>
            <h2 className="ptitle">International <em>faculty</em></h2>
            <p className="ptext">Prof. Marcin Barczyński (Jagiellonian University, Kraków) joins the faculty for the surgical and expanding-indications perspective.</p>
          </div>
        </section>

        {/* Panel 7: Evidence, honestly weighed */}
        <section className="panel" id="evidence" data-index="6" tabIndex="0" aria-label="Evidence">
          <div className="pinner">
            <p className="eyebrow">Why attend</p>
            <h2 className="ptitle">Evidence, <em>honestly weighed</em></h2>
            <p className="ptext">Guidelines, RCT and non-RCT evidence, TI-RADS and Bethesda cytology — presented with where the evidence is strong and where it isn't.</p>
          </div>
        </section>

        {/* Panel 8: CME accredited */}
        <section className="panel" id="cme" data-index="7" tabIndex="0" aria-label="CME accredited">
          <div className="pinner">
            <p className="eyebrow">Why attend</p>
            <h2 className="ptitle">CME <em>accredited</em></h2>
            <p className="ptext">The meeting carries CME accreditation (in process) — certificates issued to registered delegates.</p>
          </div>
        </section>

        {/* Panel 9: Two days, two sites */}
        <section className="panel p-cta" id="schedule" data-index="8" tabIndex="0" aria-label="Two days, two sites">
          <div className="pinner">
            <div className="cta-meta">At a glance</div>
            <div className="cta-title">Two days, two sites</div>
            <div className="cta-venue" style={{ marginTop: '24px' }}>
              Day 1 · pre-conference workshop<br/>
              Friday, 27 Nov 2026 (13:30 – 18:30 · under ISTS 2026)<br/>
              Medanta – The Medicity, Gurgaon
              <br/><br/>
              Day 2 · IR-Tutorials<br/>
              Saturday, 28 Nov 2026 (08:30 – 15:05 · closing High Tea)<br/>
              Holiday Inn, Aerocity, New Delhi
            </div>
          </div>
        </section>

        {/* Panel 10: Faculty */}
        <section className="panel p-cta" id="faculty" data-index="9" tabIndex="0" aria-label="Faculty">
          <div className="pinner">
            <div className="cta-meta">Faculty</div>
            <div className="cta-title">23 faculty across five specialties</div>
            <div className="cta-venue" style={{ marginTop: '24px' }}>
              <b>Organising Secretary</b><br/>
              Dr. Anubhav Khandelwal, Director, Interventional Radiology, Medanta – The Medicity, Gurgaon
              <br/><br/>
              <b>Course Director</b><br/>
              Dr. S. S. Baijal, Chairman, Diagnostic &amp; Interventional Radiology, Medanta
              <br/><br/>
              <b>International Faculty</b><br/>
              Prof. Marcin Barczyński, Jagiellonian University, Kraków, Poland
            </div>
          </div>
        </section>

        {/* Panel 11: Registration */}
        <section className="panel p-cta" id="registration" data-index="10" tabIndex="0" aria-label="Registration fees">
          <div className="pinner">
            <div className="cta-title">Fees</div>
            <div className="cta-venue" style={{ marginTop: '24px' }}>
              <b>Early bird · until 15 Oct</b><br/>
              ₹3,000 consultant · ₹1,500 fellow/trainee
              <br/><br/>
              <b>Regular · 16 Oct – 20 Nov</b><br/>
              ₹5,000 consultant · ₹1,500 fellow/trainee
            </div>
            <a className="btn mt" href="#" onClick={handleRegisterClick}>Register now</a>
            <div className="eb">Hands-on workshop (IR / Radiology only) may be added during registration — seats are limited to 50. Fellows and trainees register at the concessional fee with proof of status.</div>
          </div>
        </section>

      </main>
    </>
  );
};

export default Home;
